--[[
    Forever Codex - Changelog.lua
    Release notes, newest first: Forever Gearbox and Forever Codex (Forever Tweaks and Forever
    Compendium until 3.3.0: older entries keep those names) ship at one version, so each release has
    one entry here, whichever addon it changes (up to 2.9.0 the suite's, with Forever Core; before
    that, from 0.3.0 down, Forever Compendium's own). The Changelog page shows them
    (Settings/ChangelogPage.lua); the release notes on GitHub are this file's entry.

    Each change: { module = "ModuleName" (or a title for a removed module or another addon's),
    kind = "Added" | "Changed" | "Fixed" | "Removed", text = "..." }. Without a module it goes
    under General.
]]

local _, ns = ...

ns.changelog = {
    {
        version = "3.3.0",
