        changes = {
            { kind = "Changed", text = "New names: Forever Tweaks is Forever Gearbox (/fg or /gearbox), and Forever Compendium is Forever Codex (/codex). Forever++'s settings for each module carry over by themselves. To keep your journal's book and the rest, before you first log in with the new version: close the game, and in WTF\\Account\\<account>\\SavedVariables (and each character's SavedVariables folder) copy ForeverCompendium.lua to ForeverCodex.lua and ForeverTweaks.lua to ForeverGearbox.lua. Then delete the old ForeverTweaks and ForeverCompendium addon folders." },
            { kind = "Added", text = "Forever Gearbox works without Forever++: its modules are then on its own page in Settings > AddOns > Forever Gearbox (/fg), laid out just as Forever++'s Modules page (the module list by category with a search, the chosen module's options beside it), with Advanced Graphics under it while it's on and no window of its own. Gearbox keeps their settings itself, and the modules that add to one of Forever++'s are modules of their own. Upgrade Arrows in Baganator needs Forever++. With Forever++ everything stays on its Modules page as before." },
            { module = "Drawer", kind = "Added", text = "Drawer: one action bar button opens a flyout of your spells, items and mounts, in Blizzard's own flyout look, in combat too. In the macro window, select a macro and press Make Drawer on the Drawer panel beside it, then drag spells, items and mounts onto its empty slot (right-click one to take it out); put the macro on an action bar and click it. Open Toward, Close After Click and Hide Unusable in its options. The idea is Plumber's Drawer Macro." },
            { module = "ChatButtons", kind = "Added", text = "Hide Chat Buttons, without Forever++ (Forever++ has its own): the buttons beside the chat fade out with the chat when the mouse leaves it, to Faded Buttons, and come back with it." },
            { module = "OpenMap", kind = "Added", text = "Forever Codex works with OpenMap as Questie does: its pins show for every zone in view on OpenMap's seamless map, not only the zone underneath; without Questie, OpenMap's Townsfolk and Rare Mobs come from QuestieDB; Quest Pins, Rare Pins and Creature Areas are switches in OpenMap's menu; and a dungeon's map lists the creatures you've met there." },
            { module = "Visuals", kind = "Changed", text = "Advanced Graphics is easier to read: its settings in two columns (Look, Image and World Detail; Lighting & Atmosphere and Camera & Interaction), and Dynamic Light below them as a part of its own, under a divider and a big heading, its \"Now\" line in a box of its own and its Defaults button Blizzard's size." },
            { module = "Map Pan & Zoom", kind = "Removed", text = "Map Pan & Zoom, Melee Range and Keep Windows Open are gone, with and without Forever++. What they saved is cleared; the map and windows are the game's own again." },
            { module = "Visuals", kind = "Changed", text = "Visuals is Advanced Graphics: one page for how the game looks on top of its graphics menu, Dynamic Light no longer a page of its own: Look (presets, Protect Values), Image (Brightness, Contrast, and now Gamma, sharpening), Lighting & Atmosphere, Dynamic Light (its sections show while it's on, with a line saying what it sets now and why), World Detail, Camera & Interaction. Blizzard Default and Before turn Dynamic Light off too. Dynamic Light keeps the light right in combat and puts its own back when something else changes it. Its fades are smooth: 20 small steps a second, easing in as eyes adjust, and walking in or out of a capital or Undercity blends over City Fade (30 seconds), as DynamicLight does." },
            { module = "Visuals", kind = "Fixed", text = "Advanced Graphics' sky is drawn again: it is a real vertical gradient now, not a flat colour (the texture was asked for a method widgets keep out of their own fields, so every update fell back to a plain fill), it is a night-blue veil that is strongest at the top of the screen and fades to nothing at its lower edge (it ended on a visible line through the world before, with the light colour at the bottom), and its fade follows the game's clock by itself instead of waiting for a setting to change or a loading screen. With Dynamic Light off, the Sky section's Sunrise, Sunset and Twilight set the curve; with it on, its Time section does. Night Only masks the day rather than dimming the night (by night it changes nothing, as it was already at full). An old static gradient alpha carries over at the strength it had at night." },
            { module = "Visuals", kind = "Removed", text = "Loot Sparkles: Forever++'s Quest Item Sparkles does it. Protect Values no longer puts the sparkle or its Outline Mode back." },
            { module = "Visuals", kind = "Changed", text = "Dynamic Light has a Day level of its own (50 brightness, 50 contrast, 1.0 gamma, as DynamicLight's), so it shows by day too; your own Brightness and Contrast come back when it's off. Turned on, it's there at once (only later changes ease in), as DynamicLight does." },
            { module = "Visuals", kind = "Added", text = "Dynamic Light: every zone and city of Kalimdor and the Eastern Kingdoms can have its own strength and its own Day light (pick it on the page, or stay with the zone you're in; a * marks the ones you set). Use My Brightness and Contrast starts Day from your own values to fine-tune. Capitals are known by their map in any language, all of them, with Undercity its own." },
            { module = "Journal", kind = "Added", text = "Open On: the journal opens where you left it, on the creatures of the zone you're in, or on your first pinned creature (where you left it when there's none)." },
            { kind = "Fixed", text = "Forever Gearbox' modules on Forever++'s page no longer show a notice's button while its notice doesn't apply (such as Fade Chat Messages' Open Forever++ for Keep Chat Visible, which is gone): Forever++ can't hide a plugin's button with its notice, so only the notice's text is there. Gearbox' own page without Forever++ still has them." },
