            { module = "QuestPins", kind = "Added", text = "Quest Kinds, Upcoming Quests, Group Spawns and Pin Colors options. Quests you can take follow Forever++'s current rules: Forever's new races by their own bit, professions at the rank a quest needs, and holiday, dungeon and repeatable quests when you ask for them." },
            { module = "QuestFocus", kind = "Added", text = "Quest on the Map: a quest page's Show on Map, or a Ctrl-click on any quest in the journal, shows that quest on the world map and the minimap from QuestieDB: where it starts, where it's turned in and where its objectives are." },
